('prometheus', 'Prometheus Metrics & Exporter', 'observability', 'Exposes Prometheus pull metrics endpoint on port 9145 with NGINX status scraping and OTLP push.', 1, '{"enabled":true,"port":9145,"stub_status_url":"http://127.0.0.1:80/stub_status","prometheus":{"enabled":true,"path":"/metrics"},"otlp":{"enabled":false,"endpoint":"","interval_secs":15}}'),
('opentelemetry', 'OpenTelemetry Distributed Tracing', 'observability', 'W3C TraceContext propagation and OTel exporter to Jaeger, Tempo, and Honeycomb.', 0, '{"enabled":true,"endpoint":"http://127.0.0.1:4317","protocol":"grpc","service_name":"aurora-gateway","sampling_rate":0.05,"propagation_format":"w3c"}'),
('zipkin', 'Zipkin B3 Distributed Tracing', 'observability', 'Injects B3 propagation headers and exports trace spans to Zipkin collector.', 0, '{"enabled":true,"endpoint":"http://127.0.0.1:9411/api/v2/spans","sample_rate":0.1,"b3_header_propagation":true}'),
('datadog', 'Datadog APM & StatsD Exporter', 'observability', 'Emits low-latency DogStatsD metrics and tracing envelopes to Datadog agent daemon.', 0, '{"enabled":true,"statsd_host":"127.0.0.1","statsd_port":8125,"sample_rate":1,"tags":["env:production","service:aurora-gateway","cluster:primary"]}'),
('access-log', 'Zero-Copy Structured JSON Access Log', 'observability', 'High-throughput structured access logging with custom fields and zero-copy ring buffers.', 0, '{"enabled":true,"format":"json","output":"/var/log/aurora/access.log","buffer_size":1024,"flush_interval_ms":500,"include_headers":["Host","User-Agent","X-Request-ID"]}'),
('http-logger', 'HTTP REST Log Emitter', 'observability', 'Streams request and response log envelopes over HTTP POST to centralized logging collectors.', 0, '{"enabled":true,"endpoint":"http://127.0.0.1:8088/logs","method":"POST","batch_size":100,"flush_interval_secs":5,"timeout_ms":3000}'),
('syslog-logger', 'RFC 5424 Syslog Log Streamer', 'observability', 'Emits RFC 5424 compliant log messages over UDP, TCP, or TLS to Syslog collectors.', 0, '{"enabled":true,"host":"127.0.0.1","port":514,"facility":"local0","protocol":"udp","tag":"aurora-gateway"}'),
('kafka-logger', 'Apache Kafka Access Event Producer', 'observability', 'High-throughput real-time streaming of access events directly to Kafka topics.', 0, '{"enabled":true,"brokers":["127.0.0.1:9092"],"topic":"aurora-access-logs","compression":"gzip","producer_acks":"all"}'),
('loki-logger', 'Grafana Loki Log Exporter', 'observability', 'Pushes structured stream logs directly to Grafana Loki HTTP push API.', 0, '{"enabled":true,"endpoint":"http://127.0.0.1:3100/loki/api/v1/push","tenant_id":"tenant_prod","labels":{"job":"aurora-api-gateway","env":"production"}}'),
('elasticsearch-logger', 'Elasticsearch & OpenSearch Bulk Indexer', 'observability', 'Direct bulk indexing of HTTP request records into Elasticsearch or OpenSearch clusters.', 0, '{"enabled":true,"endpoint":"http://127.0.0.1:9200","index":"aurora-logs-%Y.%m.%d","batch_size":200,"auth":{"username":"elastic","password":"changeme"}}'),
('request-id', 'Unique X-Request-ID Injector', 'observability', 'Generates and propagates UUIDv4 or Snowflake unique trace IDs across upstream hops.', 0, '{"enabled":true,"header_name":"X-Request-ID","generate_if_missing":true,"format":"uuid4","preserve_incoming":true}'),
('audit-log', 'Tamper-Proof Admin Audit Trail', 'observability', 'Logs all configuration mutations and administrative actions into an immutable audit stream.', 1, '{"enabled":true,"output":"/var/log/aurora/audit.log","hash_chain":true,"log_mutations_only":true}'),

-- 8. Resilience & Upstream (10)
('circuit-breaker', 'Automated Upstream Circuit Breaker', 'resilience_upstream', 'Trips failing upstream endpoints and isolates unhealthy nodes during cascading failures.', 0, '{"enabled":true,"error_threshold_percentage":50,"minimum_requests":20,"recovery_timeout_secs":30,"half_open_success_threshold":5}'),
('retry-policy', 'Exponential Backoff Retry Engine', 'resilience_upstream', 'Automatically retries idempotent requests on upstream 502, 503, and 504 network errors.', 0, '{"enabled":true,"retries":3,"backoff_base_ms":100,"max_backoff_ms":1000,"retry_on":["http_502","http_503","http_504","connect_failure"]}'),
('timeout-policy', 'Strict Connection & Read Timeouts', 'resilience_upstream', 'Enforces connect, read, and write timeout limits to eliminate resource leakage.', 0, '{"enabled":true,"connect_timeout_ms":2000,"read_timeout_ms":10000,"write_timeout_ms":10000}'),
('outlier-detection', 'Consecutive Error Outlier Detection', 'resilience_upstream', 'Identifies and ejects anomalous high-error upstream servers from active load balancing.', 0, '{"enabled":true,"consecutive_5xx":5,"ejection_duration_secs":30,"max_ejection_percent":50,"enforce_interval_secs":10}'),
('active-health-check', 'Synthetic Probe Active Health Checking', 'resilience_upstream', 'Periodically sends synthetic HTTP GET or gRPC health checks to verify upstream health.', 0, '{"enabled":true,"path":"/healthz","interval_secs":10,"timeout_secs":2,"healthy_threshold":2,"unhealthy_threshold":3,"expected_statuses":[200,204]}'),
('passive-health-check', 'Live Traffic Passive Health Checking', 'resilience_upstream', 'Monitors live request failures and dynamically marks unhealthy origins as down.', 0, '{"enabled":true,"max_fails":3,"fail_timeout_secs":10,"unhealthy_statuses":[500,502,503,504]}'),
('fallback-upstream', 'Disaster Recovery Fallback Origin', 'resilience_upstream', 'Automatically redirects traffic to a designated fallback backup origin if main cluster fails.', 0, '{"enabled":true,"primary_upstream":"backend_primary","fallback_upstream":"backend_dr","trigger_on_status":[500,502,503,504]}'),
('hedged-request', 'Speculative Hedged Requests', 'resilience_upstream', 'Sends speculative duplicate requests to cut p99 tail latency in critical microservices.', 0, '{"enabled":true,"hedged_delay_ms":150,"max_hedged_attempts":2}'),
('upstream-affinity', 'Session Affinity & Sticky Cookie', 'resilience_upstream', 'Pins client sessions to specific upstream servers using cookies or consistent IP hashing.', 0, '{"enabled":true,"cookie_name":"AURORA_STICKY","ttl_secs":3600,"hash_strategy":"ip_hash","failover":"next_node"}'),
('adaptive-concurrency', 'Gradient Adaptive Concurrency Control', 'resilience_upstream', 'Dynamically adjusts maximum concurrent requests based on measured latency gradients.', 0, '{"enabled":true,"min_concurrency":10,"max_concurrency":1000,"target_rtt_ms":50,"gradient_smoothing":0.2}'),

