('proxy-cache', 'Edge Memory & Disk HTTP Proxy Cache', 'cache_content', 'Caches GET/HEAD responses with RFC-compliant Cache-Control and stale-while-revalidate.', 0, '{"enabled":true,"cache_size_mb":512,"default_ttl_secs":60,"stale_while_revalidate":true,"methods":["GET","HEAD"],"cache_key":"$scheme$request_method$host$request_uri"}'),
('redis-cache', 'Distributed Redis Microservice Cache', 'cache_content', 'Shared distributed caching across all WAF nodes using Redis key-value store.', 0, '{"enabled":true,"redis_url":"redis://127.0.0.1:6379/2","default_ttl_secs":300,"key_prefix":"aurora:cache:","compress_payloads":true}'),
('cache-purge', 'Instant Cache Invalidation API', 'cache_content', 'Provides instant cache eviction by URL or wildcard tag via HTTP PURGE requests.', 0, '{"enabled":true,"allowed_ips":["127.0.0.1","10.0.0.0/8"],"purge_key_header":"X-Purge-Key","purge_method":"PURGE"}'),
('etag', 'Dynamic Strong & Weak ETag Generator', 'cache_content', 'Computes SHA-256 ETags and handles 304 Not Modified conditional validation.', 0, '{"enabled":true,"weak":true,"algorithm":"sha256"}'),
('conditional-request', 'Conditional Request Evaluator', 'cache_content', 'Validates If-Match, If-None-Match, If-Modified-Since headers to optimize network transit.', 0, '{"enabled":true,"evaluate_if_match":true,"evaluate_if_none_match":true,"evaluate_if_modified_since":true}'),
('static-response', 'Static File & Mock JSON Server', 'cache_content', 'Directly serves static HTML, CSS, or mock JSON responses without contacting upstreams.', 0, '{"enabled":true,"root_dir":"/var/www/static","autoindex":false,"index_files":["index.html","index.htm"]}'),
('mock-response', 'Parameter-Aware Mock Response Engine', 'cache_content', 'Returns dynamic mock responses based on request path and parameters for API testing.', 0, '{"enabled":true,"routes":{"/api/v1/mock/ping":{"status":200,"body":"{\"status\":\"ok\",\"service\":\"mock\"}"}}}'),
('response-buffering', 'Smart Response Buffering & Streaming', 'cache_content', 'Configures memory buffer thresholds versus unbuffered real-time SSE streaming.', 0, '{"enabled":true,"buffer_size_kb":64,"disable_for_sse":true,"disable_for_grpc":true}'),

