('ai-prompt-guard', 'Prompt Injection & Jailbreak Defense', 'ai_gateway', 'Real-time heuristic and neural screening blocking adversarial prompt injections.', 0, '{"enabled":true,"detect_jailbreak":true,"detect_pii":true,"detect_prompt_injection":true,"action":"block","rejected_response":"Prompt rejected: adversarial content or policy violation detected"}'),
